button--narrow-screen.snippet:
import { Component } from '@angular/core';
import { ButtonComponent } from './button.component';
import {
  IconArrowRightComponent,
  IconCloseComponent,
  IconMenuComponent,
  IconPlusComponent,
} from '../icon';

@Component({
  selector: 'app-demo',
  imports: [ButtonComponent, IconArrowRightComponent, IconCloseComponent, IconMenuComponent, IconPlusComponent],
  template: `
    <div class="column">
        <div class="row">
            <button dma-button type="button" kind="quiet" aria-label="Menu">
                <dma-icon-menu />
            </button>
            <button dma-button type="button" kind="quiet" aria-label="Close">
                <dma-icon-close />
            </button>
        </div>
        <button dma-button type="button" [kind]="kind">{{ label }}</button>
    </div>`,
})
export class DemoComponent {
  kind = 'secondary';
  label = 'Label';
}
